mapper.select:
SELECT 
FROM 0721acgn.tb_galgame


        AND (
            genres = #{genre}
            OR LOCATE(#{genre}, IFNULL(genres, '')) > 0
        )


        AND release_year >= #{yearMin}


        AND release_year <= #{yearMax}




        ORDER BY rating IS NULL ASC, rating DESC, rating_count DESC, id ASC


        ORDER BY release_year IS NULL ASC, release_year DESC, release_date DESC, id ASC


        ORDER BY sort_order ASC, id ASC


LIMIT #{offset}, 20
